import { BadRequestError } from './BadRequestError';

function fieldOf(source: unknown, key: string): unknown {
  return typeof source === 'object' && source !== null
    ? (source as Record<string, unknown>)[key]
    : undefined;
}

export function optionalString(source: unknown, key: string): string | undefined {
  const value = fieldOf(source, key);
  if (value === undefined || value === null) {
    return undefined;
  }
  if (typeof value !== 'string') {
    throw new BadRequestError(`'${key}' must be a string`);
  }
  return value;
}

export function requiredString(source: unknown, key: string): string {
  const value = optionalString(source, key);
  if (value === undefined) {
    throw new BadRequestError(`'${key}' is required`);
  }
  return value;
}

